<template>
  <main class="min-h-screen bg-[#0d0e12] px-4 py-6 text-zinc-100 sm:px-6"><div class="mx-auto max-w-5xl"><RouterLink to="/" class="text-sm text-amber-300">← 返回工作台</RouterLink><div class="mt-6"><p class="text-[10px] uppercase tracking-[0.18em] text-amber-500">STYLE CATALOG</p><h1 class="mt-1 text-2xl font-semibold">款式库 / 对货助手</h1><p class="mt-2 text-sm text-zinc-400">把自己经手的款式和柜台库存记下来，现场按款号、名称快速查找。数据保存在本机。</p></div><div class="mt-6 grid gap-5 lg:grid-cols-[340px_minmax(0,1fr)]"><form class="h-fit space-y-3 border border-zinc-800 bg-[#141519] p-4" @submit.prevent="addItem"><h2 class="text-sm font-semibold">登记款式</h2><label class="block text-xs text-zinc-400">款号<input v-model.trim="form.code" required maxlength="40" class="field" placeholder="如 A102" /></label><label class="block text-xs text-zinc-400">名称 / 描述<input v-model.trim="form.name" required maxlength="100" class="field" placeholder="如 祥云古法手镯" /></label><div class="grid grid-cols-2 gap-3"><label class="text-xs text-zinc-400">库存件数<input v-model.number="form.stock" type="number" min="0" step="1" class="field" /></label><label class="text-xs text-zinc-400">克重（g）<input v-model.number="form.weight" type="number" min="0" step="0.001" class="field" /></label></div><label class="block text-xs text-zinc-400">柜台 / 供应商<input v-model.trim="form.counter" maxlength="60" class="field" placeholder="用于现场对货" /></label><label class="block text-xs text-zinc-400">参考照片<input type="file" accept="image/*" class="mt-2 block w-full text-xs text-zinc-400 file:mr-3 file:border file:border-zinc-700 file:bg-zinc-900 file:px-3 file:py-2 file:text-xs file:text-zinc-200" @change="handleImage" /></label><button class="w-full bg-amber-400 px-4 py-2.5 text-sm font-semibold text-zinc-950">保存到款式库</button><p v-if="message" class="text-xs text-emerald-300">{{ message }}</p></form><section><div class="flex flex-wrap gap-2"><input v-model.trim="query" class="min-w-48 flex-1 border border-zinc-700 bg-[#141519] px-3 py-2.5 text-sm text-zinc-100 outline-none focus:border-amber-400/60" placeholder="搜索款号、名称、柜台" /><span class="self-center text-xs text-zinc-500">{{ filtered.length }} 款</span></div><ul v-if="filtered.length" class="mt-3 divide-y divide-zinc-800 border-y border-zinc-800"> <li v-for="item in filtered" :key="item.id" class="flex gap-3 py-3"><img v-if="item.image" :src="item.image" class="h-20 w-20 shrink-0 object-cover" alt="款式参考图" /><div class="min-w-0 flex-1"><div class="flex flex-wrap items-center gap-2"><span class="font-mono text-xs text-amber-300">{{ item.code }}</span><span class="text-sm font-medium">{{ item.name }}</span></div><p class="mt-1 text-xs text-zinc-400">库存 {{ item.stock }} 件<span v-if="item.weight"> · {{ Number(item.weight).toFixed(3) }} g</span></p><p v-if="item.counter" class="mt-1 text-xs text-zinc-500">{{ item.counter }}</p></div><button class="self-start text-xs text-rose-300" @click="remove(item.id)">删除</button></li></ul><p v-else class="mt-8 border-y border-zinc-800 py-8 text-center text-sm text-zinc-500">{{ query ? '没有匹配的款式，可调整关键词搜索。' : '款式库还是空的，先登记经手款号和库存。' }}</p><p class="mt-3 text-[11px] leading-5 text-zinc-600">此工具不会自动识别或跨店查询图片；请用款号和描述建立自己的清单。图片与数据仅存于当前浏览器。</p></section></div></div></main>
</template>
<script setup>
import { computed, onMounted, reactive, ref, watch } from 'vue';
const KEY = 'shuibei-catalog-v1'; const items = ref([]); const query = ref(''); const message = ref(''); const image = ref(''); const form = reactive({ code: '', name: '', stock: 1, weight: '', counter: '' });
const filtered = computed(() => { const q = query.value.toLowerCase(); return items.value.filter((item) => `${item.code} ${item.name} ${item.counter}`.toLowerCase().includes(q)); });
onMounted(() => { try { items.value = JSON.parse(localStorage.getItem(KEY) || '[]'); } catch { items.value = []; } });
watch(items, (value) => { try { localStorage.setItem(KEY, JSON.stringify(value)); } catch { message.value = '本机存储已满，请删除较大的图片后重试。'; } }, { deep: true });
function handleImage(event) { const file = event.target.files?.[0]; if (!file) return; if (!file.type.startsWith('image/') || file.size > 1024 * 1024) { message.value = '请选择 1MB 以内的图片。'; return; } const reader = new FileReader(); reader.onload = () => image.value = String(reader.result || ''); reader.readAsDataURL(file); }
function addItem() { const duplicate = items.value.find((item) => item.code.toLowerCase() === form.code.toLowerCase()); const entry = { id: duplicate?.id || `${Date.now()}`, ...form, image: image.value }; if (duplicate) items.value = items.value.map((item) => item.id === duplicate.id ? entry : item); else items.value.unshift(entry); Object.assign(form, { code: '', name: '', stock: 1, weight: '', counter: '' }); image.value = ''; message.value = '款式已保存到本机。'; }
function remove(id) { items.value = items.value.filter((item) => item.id !== id); }
</script>
<style scoped>.field{margin-top:.375rem;width:100%;border:1px solid rgb(63 63 70);background:#0d0e12;padding:.625rem .75rem;color:#f4f4f5;outline:none}.field:focus{border-color:rgb(251 191 36 / .6)}</style>
